content:
yakit.AutoInitYakit()

SPACE = str.ToUpper(str.TrimSpace(cli.String("space-engine")))
// 处理查询语句
query = cli.String("query")
if query == "" {
    yakit.Error(f"{SPACE} 查询语句为空")
    return
}
Apikey = cli.String("api-key")
ApiAccount = cli.String("api-account")
FetchPage = cli.Int("fetch-page",cli.setDefault(1))
FetchSize = cli.Int("fetch-size",cli.setDefault(100))

APIkeyFieldName = f`BATCH_HACK_${SPACE}_APIKEY`
APIAccountFieldName = f`BATCH_HACK_${SPACE}_USERNAME`

saveApiKey = !cli.Have("no-save-api-key")
if saveApiKey {
            yakit.Info(f"自动保存 ${SPACE} APIKey ")
            db.SetKey(APIkeyFieldName, Apikey)
            db.SetKey(APIAccountFieldName, ApiAccount)
}

if Apikey == "" {
    Apikey = db.GetKey(APIkeyFieldName)
}

if ApiAccount == "" {
    ApiAccount = db.GetKey(APIAccountFieldName)
}

if SPACE == "FOFA" || SPACE == "HUNTER"{
 if  ApiAccount == "" {
        yakit.Info(f"${SPACE} APIAccount 为空")
        return
    }
}

if Apikey == ""{
    yakit.Info(f"${SPACE} APIKey 为空")
    return
}


yakit.Info(f"${SPACE} API 信息: Account:${ApiAccount},KEY:${Apikey},FetchPage:${FetchPage},FetchSize:${FetchSize}")

outputTable = func(r) {
    data = make(map[string]var)
    data["Addr"] = r.Addr
    data["FromEngine"] = r.FromEngine
    data["Latitude"] = r.Latitude
    data["Longitude"] = r.Longitude
    data["HtmlTitle"] = r.HtmlTitle      
    data["Domains"] = r.Domains        
    data["Province"] = r.Province       
    data["Url"] = r.Url            
    data["ConfirmHttps"] = r.ConfirmHttps 
    data["Host"] = r.Host           
    data["City"] = r.City           
    data["Asn"] = r.Asn            
    data["Location"] = r.Location       
    data["ServiceProvider"] = r.ServiceProvider
    data["FromFilter"] = r.FromFilter     
    data["Fingerprints"] = r.Fingerprints   
    data["Banner"] = r.Banner       
    yakit.TableData(f"${SPACE}结果表", data)
}

switch SPACE {
case "FOFA":
    yakit.EnableTable(f"${SPACE}结果表", ["Addr","Host","HtmlTitle","Domains","Url","Location","City","FromFilter"])
    res, err := spacengine.FofaQuery(ApiAccount,Apikey,query, spacengine.maxPage(FetchPage),spacengine.maxRecord(FetchSize))
    //yakit.Info("res"+res)
    if err != nil{
        yakit.Error(f"${SPACE}搜索出错%v",err)
        return
    }

    for r := range res {
        log.info("%v %v %v %v %v", r.Addr,r.Host,r.HtmlTitle,r.Domains,r.Url)
        outputTable(r)
    }
case "HUNTER":
    yakit.EnableTable(f"${SPACE}结果表", ["Addr","Host","HtmlTitle","Domains","Url","Location","ServiceProvider","FromFilter"])
        res, err := spacengine.HunterQuery(ApiAccount,Apikey,query, spacengine.maxPage(FetchPage),spacengine.maxRecord(FetchSize))
    //yakit.Info("res"+res)
    if err != nil{
        yakit.Error("fofa搜索出错%v",err)
        return
    }

    for r := range res {
        log.info("%v %v %v %v %v", r.Addr,r.Host,r.HtmlTitle,r.Domains,r.Url)
        outputTable(r)
    }
case "ZOOMEYE":
  yakit.EnableTable(f"${SPACE}结果表", ["Addr","Host","Location","ServiceProvider","City","Latitude","Longitude","FromFilter"])
        res, err := spacengine.ZoomeyeQuery(Apikey,query, spacengine.maxPage(FetchPage),spacengine.maxRecord(FetchSize))
    //yakit.Info("res"+res)
    if err != nil{
        yakit.Error(f"${SPACE}搜索出错%v",err)
        return
    }

    for r := range res {
        log.info("%v %v %v %v %v", r.Addr,r.Host,r.HtmlTitle,r.Domains,r.Url)
        outputTable(r)
    }
case "SHODAN":
  yakit.EnableTable(f"${SPACE}结果表", ["Addr","Host","Domains","Location","ServiceProvider","City","Latitude","Longitude","FromFilter"])
        res, err := spacengine.ShodanQuery(Apikey,query, spacengine.maxPage(FetchPage),spacengine.maxRecord(FetchSize))
    //yakit.Info("res"+res)
    if err != nil{
        yakit.Error(f"${SPACE}搜索出错%v",err)
        return
    }

    for r := range res {
        log.info("%v %v %v %v %v", r.Addr,r.Host,r.HtmlTitle,r.Domains,r.Url)
        outputTable(r)
    }
case "QUAKE":
  yakit.EnableTable(f"${SPACE}结果表", ["Addr","Host","HtmlTitle","Domains","Location","ServiceProvider","City","Latitude","Longitude","FromFilter"])
        res, err := spacengine.QuakeQuery(Apikey,query, spacengine.maxPage(FetchPage),spacengine.maxRecord(FetchSize))
    //yakit.Info("res"+res)
    if err != nil{
        yakit.Error(f"${SPACE}搜索出错%v",err)
        return
    }

    for r := range res {
        log.info("%v %v %v %v %v", r.Addr,r.Host,r.HtmlTitle,r.Domains,r.Url)
        outputTable(r)
    }

default:
        yakit.Info("不匹配的空间引擎类型:%s",SPACE)
        return
}
